// Ingest input and normalize to a devices array
const inputItems = $input.all().map(i => i.json);

function isDevice(obj) {
  return obj && typeof obj === 'object' &&
    ('deviceId' in obj) &&
    obj.antivirus && obj.operatingSystem;
}

let devices = [];
for (const j of inputItems) {
  if (Array.isArray(j)) {
    for (const x of j) if (isDevice(x)) devices.push(x);
    continue;
  }
  if (Array.isArray(j?.results)) {
    for (const x of j.results) if (isDevice(x)) devices.push(x);
    continue;
  }
  if (isDevice(j)) devices.push(j);
}

// Helpers
function normalizeState(state) {
  const t = String(state ?? '').trim().toUpperCase();
  if (t === 'ON' || t === 'ACTIVE' || t === 'ENABLED' || t.includes(' ON') || t.startsWith('ON ')) return 'ON';
  if (t === 'OFF' || t === 'DISABLED' || t === 'SNOOZED' || t === 'EXPIRED' || t.includes(' OFF') || t.startsWith('OFF ')) return 'OFF';
  return 'UNKNOWN';
}
function normalizeDef(def) {
  const t = String(def ?? '').trim().toUpperCase().replace(/\s+/g, '-');
  if (t.includes('UP-TO-DATE')) return 'Up-to-Date';
  if (t.includes('OUT-OF-DATE') || t.includes('OUT-OFDATE') || t.includes('OUTOFDATE')) return 'Out-of-Date';
  return 'Unknown';
}

const totalDevices = devices.length;

// Initialize counters and collections
let protectedEndpoints = 0;
let unprotectedEndpoints = 0;
let operatingSystems = {};
let antivirusProducts = {};
let outdatedDefinitions = 0;
let antivirusOff = 0;

// Patch counters
let totalMissingPatches = 0;
let devicesWithMissingPatches = 0;
let devicesFullyPatched = 0;
const devicesMissingPatchesBreakdown = [];

// Vulnerability counters
let devicesWithCriticalVulns = 0;
let devicesWithHighVulns = 0;
let totalCriticalVulns = 0;
let totalHighVulns = 0;
const devicesWithVulnsBreakdown = []; // { deviceId, deviceName, critical, high, medium, low }

// Security status counters
let securityStatus = {
  fullyProtected: 0,
  partiallyProtected: 0,
  unprotected: 0,
  unknown: 0
};

// Process each device
for (const device of devices) {
  const antivirus = device.antivirus || {};
  const os = device.operatingSystem || {};
  const patches = device.patches || {};
  const vulns = device.vulnerabilities || {};

  const productName = (antivirus.productName || '').trim();
  const productState = normalizeState(antivirus.productState);
  const defStatus = normalizeDef(antivirus.definitionStatus);

  // Count protection status
  if (!productName || productName.toUpperCase() === 'NONE') {
    unprotectedEndpoints++;
    securityStatus.unprotected++;
  } else {
    protectedEndpoints++;

    if (productState === 'ON') {
      if (defStatus === 'Up-to-Date') {
        securityStatus.fullyProtected++;
      } else if (defStatus === 'Out-of-Date') {
        securityStatus.partiallyProtected++;
        outdatedDefinitions++;
      } else {
        securityStatus.partiallyProtected++;
      }
    } else if (productState === 'OFF') {
      antivirusOff++;
      securityStatus.partiallyProtected++;
    } else {
      securityStatus.unknown++;
    }
  }

  // Count antivirus products
  const avKey = productName || 'NONE';
  antivirusProducts[avKey] = (antivirusProducts[avKey] || 0) + 1;

  // Count operating systems
  const osName = (os.name || 'Unknown').trim();
  const osKey = `${osName} ${os.releaseId || ''}`.trim();

  if (!operatingSystems[osName]) {
    operatingSystems[osName] = { total: 0, versions: {} };
  }

  operatingSystems[osName].total++;
  operatingSystems[osName].versions[osKey] = (operatingSystems[osName].versions[osKey] || 0) + 1;

  // Count missing patches
  const missingCount = Number(patches.missingPatchCount) || 0;
  const missingPatchesList = Array.isArray(patches.missingPatches) ? patches.missingPatches : [];

  totalMissingPatches += missingCount;

  if (missingCount > 0) {
    devicesWithMissingPatches++;
    devicesMissingPatchesBreakdown.push({
      deviceId: device.deviceId,
      deviceName: device.deviceName ?? `Device ${device.deviceId}`,
      missingPatchCount: missingCount,
      missingPatches: missingPatchesList
    });
  } else {
    devicesFullyPatched++;
  }

  // Count vulnerabilities
  const criticalCount = Number(vulns.critical) || 0;
  const highCount = Number(vulns.high) || 0;
  const mediumCount = Number(vulns.medium) || 0;
  const lowCount = Number(vulns.low) || 0;

  totalCriticalVulns += criticalCount;
  totalHighVulns += highCount;

  if (criticalCount > 0) devicesWithCriticalVulns++;
  if (highCount > 0) devicesWithHighVulns++;

  if (criticalCount > 0 || highCount > 0) {
    devicesWithVulnsBreakdown.push({
      deviceId: device.deviceId,
      deviceName: device.deviceName ?? `Device ${device.deviceId}`,
      critical: criticalCount,
      high: highCount,
      medium: mediumCount,
      low: lowCount,
    });
  }
}

// Calculate percentages (guard divide-by-zero)
const protectedPercentage = totalDevices ? ((protectedEndpoints / totalDevices) * 100).toFixed(1) : '0.0';
const unprotectedPercentage = totalDevices ? ((unprotectedEndpoints / totalDevices) * 100).toFixed(1) : '0.0';
const patchCompliancePercentage = totalDevices ? ((devicesFullyPatched / totalDevices) * 100).toFixed(1) : '0.0';

// Identify security risks
const securityRisks = [];
if (unprotectedEndpoints > 0) securityRisks.push(`${unprotectedEndpoints} endpoints have no antivirus protection`);
if (outdatedDefinitions > 0) securityRisks.push(`${outdatedDefinitions} endpoints have outdated antivirus definitions`);
if (antivirusOff > 0) securityRisks.push(`${antivirusOff} endpoints have antivirus disabled`);
if (totalMissingPatches > 0) securityRisks.push(`${totalMissingPatches} missing patches across ${devicesWithMissingPatches} endpoints`);
if (devicesWithCriticalVulns > 0) securityRisks.push(`${devicesWithCriticalVulns} endpoints have critical vulnerabilities`);
if (devicesWithHighVulns > 0) securityRisks.push(`${devicesWithHighVulns} endpoints have high-severity vulnerabilities`);

// Find most common OS
const mostCommonOS = Object.entries(operatingSystems).sort((a, b) => b[1].total - a[1].total)[0];

// Find legacy/unsupported systems
const legacySystems = Object.entries(operatingSystems)
  .filter(([osName]) =>
    osName.includes('Windows 10') ||
    osName.includes('Server 2012') ||
    osName.includes('Server 2016') ||
    osName.includes('1809')
  )
  .reduce((total, [, osData]) => total + osData.total, 0);

// Sort devices with missing patches by count descending
devicesMissingPatchesBreakdown.sort((a, b) => b.missingPatchCount - a.missingPatchCount);

// Sort devices with vulns: critical desc, then high desc
devicesWithVulnsBreakdown.sort((a, b) => b.critical - a.critical || b.high - a.high);

// Create summary object
const endpointSummary = {
  type: 'endpoint_summary',
  processedAt: new Date().toISOString(),

  // Core metrics
  totalEndpoints: totalDevices,
  protectedEndpoints: protectedEndpoints,
  unprotectedEndpoints: unprotectedEndpoints,
  protectedPercentage: parseFloat(protectedPercentage),
  unprotectedPercentage: parseFloat(unprotectedPercentage),

  // Patch metrics
  totalMissingPatches: totalMissingPatches,
  devicesWithMissingPatches: devicesWithMissingPatches,
  devicesFullyPatched: devicesFullyPatched,
  patchCompliancePercentage: parseFloat(patchCompliancePercentage),
  averageMissingPatchesPerDevice: totalDevices ? parseFloat((totalMissingPatches / totalDevices).toFixed(2)) : 0,

  // Security status breakdown
  securityStatus: {
    fullyProtected: securityStatus.fullyProtected,
    partiallyProtected: securityStatus.partiallyProtected,
    unprotected: securityStatus.unprotected,
    unknown: securityStatus.unknown
  },

  // Security metrics
  outdatedDefinitions: outdatedDefinitions,
  antivirusDisabled: antivirusOff,
  securityScore: totalDevices ? ((securityStatus.fullyProtected / totalDevices) * 100).toFixed(1) : '0.0',

  // Operating system breakdown
  operatingSystemSummary: {
    totalOSTypes: Object.keys(operatingSystems).length,
    mostCommonOS: mostCommonOS ? mostCommonOS[0] : 'Unknown',
    mostCommonOSCount: mostCommonOS ? mostCommonOS[1].total : 0,
    legacySystemsCount: legacySystems,
    legacySystemsPercentage: totalDevices ? ((legacySystems / totalDevices) * 100).toFixed(1) : '0.0'
  },

  // Patch breakdown
  patchSummary: {
    totalMissingPatches: totalMissingPatches,
    devicesWithMissingPatches: devicesWithMissingPatches,
    devicesFullyPatched: devicesFullyPatched,
    patchCompliancePercentage: parseFloat(patchCompliancePercentage),
    topDevicesWithMissingPatches: devicesMissingPatchesBreakdown.slice(0, 10)
  },

  // Vulnerability breakdown
  vulnerabilitySummary: {
    devicesWithCriticalVulns: devicesWithCriticalVulns,
    devicesWithHighVulns: devicesWithHighVulns,
    totalCriticalVulns: totalCriticalVulns,
    totalHighVulns: totalHighVulns,
    topDevicesWithVulns: devicesWithVulnsBreakdown.slice(0, 10)
  },

  // Detailed breakdowns
  operatingSystemBreakdown: operatingSystems,
  antivirusProductBreakdown: antivirusProducts,

  // Security recommendations
  securityRisks: securityRisks,

  // Key insights for reporting
  keyInsights: {
    criticalFindings: securityRisks.length,
    complianceLevel:
      totalDevices && (securityStatus.fullyProtected >= totalDevices * 0.95) ? 'Good' :
      totalDevices && (securityStatus.fullyProtected >= totalDevices * 0.80) ? 'Fair' : 'Poor',
    modernizationNeeded: legacySystems > 0,
    patchingNeeded: totalMissingPatches > 0,
    immediateActions: [
      ...(devicesWithCriticalVulns > 0 ? [`Remediate critical vulnerabilities on ${devicesWithCriticalVulns} endpoints`] : []),
      ...(unprotectedEndpoints > 0 ? [`Install antivirus on ${unprotectedEndpoints} unprotected endpoints`] : []),
      ...(outdatedDefinitions > 0 ? [`Update antivirus definitions on ${outdatedDefinitions} endpoints`] : []),
      ...(antivirusOff > 0 ? [`Enable antivirus on ${antivirusOff} endpoints`] : []),
      ...(totalMissingPatches > 0 ? [`Patch ${totalMissingPatches} missing updates across ${devicesWithMissingPatches} endpoints`] : [])
    ].slice(0, 4)
  }
};

// Create simplified metrics for easy access
const quickStats = {
  totalEndpoints: totalDevices,
  protectedCount: protectedEndpoints,
  unprotectedCount: unprotectedEndpoints,
  protectionRate: `${protectedPercentage}%`,
  totalMissingPatches: totalMissingPatches,
  devicesWithMissingPatches: devicesWithMissingPatches,
  patchComplianceRate: `${patchCompliancePercentage}%`,
  devicesWithCriticalVulns: devicesWithCriticalVulns,
  devicesWithHighVulns: devicesWithHighVulns,
  securityGrade:
    totalDevices && (securityStatus.fullyProtected >= totalDevices * 0.95) ? 'A' :
    totalDevices && (securityStatus.fullyProtected >= totalDevices * 0.90) ? 'B' :
    totalDevices && (securityStatus.fullyProtected >= totalDevices * 0.80) ? 'C' :
    totalDevices && (securityStatus.fullyProtected >= totalDevices * 0.70) ? 'D' : 'F',
  riskLevel: securityRisks.length === 0 ? 'Low' :
             securityRisks.length <= 2 ? 'Medium' : 'High'
};

// Output one summary item
return [{
  json: {
    ...endpointSummary,
    quickStats,
    devicesDetailed: devices
  }
}];

// Collect AV + OS + Patches + Vulnerabilities + Devices from connected inputs
const incoming = $input.all();

let antivirusData = [];
let osData = [];
let devicesData = [];
let patchData = [];
let vulnData = [];
const deviceNameMap = new Map();

function normalizeState(state) {
  const t = String(state ?? '').trim().toUpperCase();
  if (t === 'ON' || t === 'ACTIVE' || t === 'ENABLED' || t.startsWith('ON ') || t.includes('(ON)') || t.includes(' ON ')) return 'ON';
  if (t === 'OFF' || t === 'DISABLED' || t.startsWith('OFF ') || t.includes('(OFF)') || t.includes(' OFF ')) return 'OFF';
  if (t === 'SNOOZED' || t === 'EXPIRED') return 'OFF';
  if (t === 'UNKNOWN') return 'UNKNOWN';
  return t || 'UNKNOWN';
}
function stateScore(item) {
  const name = String(item?.productName ?? '').trim().toUpperCase();
  if (name === 'NONE' || name === 'NO AV' || name === 'NO ANTIVIRUS') return -1;
  const n = normalizeState(item?.productState);
  if (n === 'ON') return 2;
  if (n === 'UNKNOWN') return 1;
  return 0;
}
function toNumber(n) {
  const v = Number(n);
  return Number.isNaN(v) ? undefined : v;
}
function strOrUnknown(v) {
  const s = v == null ? '' : String(v);
  return s.trim() === '' ? 'Unknown' : s;
}

function collectFromObject(obj) {
  if (!obj || typeof obj !== 'object') return;

  if (Array.isArray(obj.results)) {
    for (const r of obj.results) collectFromObject(r);
    return;
  }
  if (Array.isArray(obj.devices)) {
    for (const d of obj.devices) collectFromObject(d);
    return;
  }
  if (Array.isArray(obj.data?.results)) {
    for (const r of obj.data.results) collectFromObject(r);
    return;
  }
  if (Array.isArray(obj.data?.devices)) {
    for (const d of obj.data.devices) collectFromObject(d);
    return;
  }

  // Vulnerability / device-health row — checked before AV/OS/patch/device
  if (obj.deviceId !== undefined && (
    'criticalVulnerabilityCount' in obj ||
    'highVulnerabilityCount' in obj ||
    'mediumVulnerabilityCount' in obj ||
    'lowVulnerabilityCount' in obj
  )) {
    const idNum = toNumber(obj.deviceId);
    if (idNum !== undefined) {
      vulnData.push({
        deviceId: idNum,
        criticalVulnerabilityCount: toNumber(obj.criticalVulnerabilityCount) ?? 0,
        highVulnerabilityCount: toNumber(obj.highVulnerabilityCount) ?? 0,
        mediumVulnerabilityCount: toNumber(obj.mediumVulnerabilityCount) ?? 0,
        lowVulnerabilityCount: toNumber(obj.lowVulnerabilityCount) ?? 0,
        healthStatus: obj.healthStatus ?? 'UNKNOWN',
        offline: obj.offline ?? null,
      });
    }
    return;
  }

  if (obj.deviceId !== undefined && (Array.isArray(obj.patches) || Array.isArray(obj.missingPatches))) {
    const idNum = toNumber(obj.deviceId);
    if (idNum !== undefined) {
      let names = [];
      if (Array.isArray(obj.missingPatches)) {
        names = obj.missingPatches.map((p) => (typeof p === 'string' ? p : p?.name ?? null)).filter((n) => n != null);
      } else if (Array.isArray(obj.patches)) {
        names = obj.patches.map((p) => p?.name ?? null).filter((n) => n != null);
      }
      patchData.push({
        deviceId: idNum,
        missingPatchCount: obj.patchCount ?? obj.missingPatchCount ?? names.length,
        missingPatches: names,
        timestamp: toNumber(obj.timestamp) ?? toNumber(obj.lastSeen) ?? 0,
      });
    }
    return;
  }

  if (obj.deviceId !== undefined && ('productName' in obj || 'productState' in obj || 'definitionStatus' in obj)) {
    const idNum = toNumber(obj.deviceId);
    if (idNum !== undefined) {
      antivirusData.push({
        deviceId: idNum,
        productName: obj.productName ?? null,
        productState: obj.productState ?? null,
        definitionStatus: obj.definitionStatus ?? null,
        version: obj.version ?? null,
        timestamp: toNumber(obj.timestamp) ?? 0,
      });
    }
    return;
  }

  if (obj.deviceId !== undefined && ('manufacturer' in obj || 'buildNumber' in obj || 'releaseId' in obj)) {
    const idNum = toNumber(obj.deviceId);
    if (idNum !== undefined) {
      osData.push({
        deviceId: idNum,
        manufacturer: obj.manufacturer ?? null,
        name: obj.name ?? null,
        releaseId: obj.releaseId ?? null,
        timestamp: toNumber(obj.timestamp) ?? 0,
      });
    }
    return;
  }

  const looksLikeDevice =
    ('id' in obj || 'deviceId' in obj) &&
    ('displayName' in obj || 'systemName' in obj || 'dnsName' in obj || 'uid' in obj || 'nodeClass' in obj);

  if (looksLikeDevice) {
    devicesData.push(obj);
    const idNum = toNumber(obj.deviceId ?? obj.id);
    if (idNum !== undefined) {
      const name = obj.displayName ?? obj.systemName ?? obj.dnsName ?? obj.deviceName;
      if (typeof name === 'string' && name.trim() !== '') deviceNameMap.set(idNum, name);
    }
    return;
  }

  for (const v of Object.values(obj)) {
    if (Array.isArray(v)) {
      for (const e of v) collectFromObject(e);
    } else if (v && typeof v === 'object') {
      collectFromObject(v);
    }
  }
}

for (const item of incoming) {
  const j = item?.json;
  if (Array.isArray(j)) {
    for (const x of j) collectFromObject(x);
    continue;
  }
  collectFromObject(j);
}

const osDataMap = new Map();
for (const item of osData) {
  const idNum = item.deviceId;
  const existing = osDataMap.get(idNum);
  if (!existing || (toNumber(item.timestamp) ?? 0) > (toNumber(existing.timestamp) ?? 0)) {
    osDataMap.set(idNum, item);
  }
}

const antivirusDataMap = new Map();
for (const item of antivirusData) {
  const idNum = item.deviceId;
  const candidateScore = stateScore(item);
  const candidateTs = toNumber(item.timestamp) ?? 0;
  const existing = antivirusDataMap.get(idNum);
  if (!existing) {
    antivirusDataMap.set(idNum, item);
    continue;
  }
  const existingScore = stateScore(existing);
  const existingTs = toNumber(existing.timestamp) ?? 0;
  if (candidateScore > existingScore || (candidateScore === existingScore && candidateTs > existingTs)) {
    antivirusDataMap.set(idNum, item);
  }
}

const patchDataMap = new Map();
for (const item of patchData) {
  const idNum = item.deviceId;
  const existing = patchDataMap.get(idNum);
  if (!existing) {
    patchDataMap.set(idNum, item);
    continue;
  }
  const candidateTs = toNumber(item.timestamp) ?? 0;
  const existingTs = toNumber(existing.timestamp) ?? 0;
  if (item.missingPatches.length > existing.missingPatches.length ||
      (item.missingPatches.length === existing.missingPatches.length && candidateTs > existingTs)) {
    patchDataMap.set(idNum, item);
  }
}

const vulnDataMap = new Map();
for (const item of vulnData) {
  vulnDataMap.set(item.deviceId, item);
}

const deviceMap = new Map();
for (const d of devicesData) {
  const idFromId = toNumber(d.id);
  if (idFromId !== undefined) deviceMap.set(idFromId, d);
  const idFromDeviceId = toNumber(d.deviceId);
  if (idFromDeviceId !== undefined && !deviceMap.has(idFromDeviceId)) deviceMap.set(idFromDeviceId, d);
}

const allDeviceIds = new Set([
  ...antivirusData.map(i => i.deviceId),
  ...osData.map(i => i.deviceId),
  ...patchData.map(i => i.deviceId),
  ...vulnData.map(i => i.deviceId),
  ...devicesData.map(d => toNumber(d.id)).filter(n => n !== undefined),
  ...devicesData.map(d => toNumber(d.deviceId)).filter(n => n !== undefined),
  ...Array.from(deviceNameMap.keys()),
]);

const combinedResults = [];
for (const deviceId of allDeviceIds) {
  const antivirusInfo = antivirusDataMap.get(deviceId) || {};
  const osInfo = osDataMap.get(deviceId) || {};
  const deviceInfo = deviceMap.get(deviceId) || {};
  const patchInfo = patchDataMap.get(deviceId) || {};
  const vulnInfo = vulnDataMap.get(deviceId) || {};

  const deviceName =
    deviceInfo.displayName ??
    deviceInfo.systemName ??
    deviceInfo.dnsName ??
    deviceInfo.deviceName ??
    deviceNameMap.get(deviceId) ??
    `Device ${deviceId}`;

  const defStat = String(antivirusInfo.definitionStatus ?? '').trim();
  const missingPatches = Array.isArray(patchInfo.missingPatches) ? patchInfo.missingPatches : [];

  combinedResults.push({
    deviceId,
    deviceName: strOrUnknown(deviceName),
    antivirus: {
      productName: strOrUnknown(antivirusInfo.productName ?? 'Unknown'),
      productState: normalizeState(antivirusInfo.productState ?? 'UNKNOWN'),
      definitionStatus: defStat === '' ? 'Unknown' : defStat,
      version: strOrUnknown(antivirusInfo.version ?? 'Unknown'),
      timestamp: antivirusInfo.timestamp ?? 0,
    },
    operatingSystem: {
      manufacturer: strOrUnknown(osInfo.manufacturer ?? 'Unknown'),
      name: strOrUnknown(osInfo.name ?? 'Unknown'),
      releaseId: strOrUnknown(osInfo.releaseId ?? 'Unknown'),
      timestamp: osInfo.timestamp ?? (antivirusInfo.timestamp ?? 0),
    },
    patches: {
      missingPatchCount: patchInfo.missingPatchCount ?? missingPatches.length,
      missingPatches: missingPatches,
    },
    vulnerabilities: {
      critical: vulnInfo.criticalVulnerabilityCount ?? 0,
      high: vulnInfo.highVulnerabilityCount ?? 0,
      medium: vulnInfo.mediumVulnerabilityCount ?? 0,
      low: vulnInfo.lowVulnerabilityCount ?? 0,
      healthStatus: vulnInfo.healthStatus ?? 'UNKNOWN',
      offline: vulnInfo.offline ?? null,
    },
  });
}

return combinedResults.map(r => ({ json: r }));

// Robust collapse: flattens any array-shaped items too
const collected = [];
for (const item of items) {
  const v = item.json;
  if (Array.isArray(v)) collected.push(...v);
  else collected.push(v);
}
return [{ json: { devices: collected, count: collected.length } }];

// Static list of organizations with their IDs (mapped from NinjaOne)
const organizations = [
  // Client name -> NinjaOne organization ID (pull IDs with the "List NinjaOne Organizations" node)
  { "name": "Contoso Ltd", "id": 101 },
  { "name": "Fabrikam Inc", "id": 102 },
  { "name": "Northwind Traders", "id": 103 }
];

// Function to normalize strings for comparison
function normalizeString(str) {
  return str.trim().toLowerCase().replace(/\s+/g, ' ');
}

// Get the target client name from input
const targetClientName = $input.first().json['Client Name'];

if (!targetClientName) {
  throw new Error("No 'Client Name' provided in input data. Please provide a client name in the 'Client Name' field.");
}

console.log(`Looking for client: "${targetClientName}"`);

let foundOrganization = null;
let matchType = "";

// 1. Exact match (case-insensitive)
foundOrganization = organizations.find(org =>
  normalizeString(org.name) === normalizeString(targetClientName)
);
if (foundOrganization) matchType = "exact";

// 2. Partial match - target contains org name
if (!foundOrganization) {
  foundOrganization = organizations.find(org =>
    normalizeString(targetClientName).includes(normalizeString(org.name))
  );
  if (foundOrganization) matchType = "partial_target_contains_org";
}

// 3. Partial match - org name contains target
if (!foundOrganization) {
  foundOrganization = organizations.find(org =>
    normalizeString(org.name).includes(normalizeString(targetClientName))
  );
  if (foundOrganization) matchType = "partial_org_contains_target";
}

// 4. Fuzzy match - 50%+ word overlap
if (!foundOrganization) {
  const targetWords = normalizeString(targetClientName).split(' ');
  foundOrganization = organizations.find(org => {
    const orgWords = normalizeString(org.name).split(' ');
    const matchingWords = targetWords.filter(word =>
      orgWords.some(orgWord => orgWord.includes(word) || word.includes(orgWord))
    );
    return matchingWords.length >= Math.ceil(targetWords.length * 0.5);
  });
  if (foundOrganization) matchType = "fuzzy";
}

// Not found - throw with suggestions
if (!foundOrganization) {
  const allClientNames = organizations.map(org => org.name).sort();
  const suggestions = allClientNames.filter(name =>
    normalizeString(name).includes(normalizeString(targetClientName.split(' ')[0]))
  ).slice(0, 5);

  throw new Error(
    `Client "${targetClientName}" not found.\n\nAvailable clients:\n${allClientNames.join('\n')}\n\nDid you mean one of these?\n${suggestions.join('\n')}`
  );
}

console.log(`Found: ${foundOrganization.name} (ID: ${foundOrganization.id}) - Match: ${matchType}`);

return {
  json: {
    organizationId: foundOrganization.id,
    organizationName: foundOrganization.name,
    searchTerm: targetClientName,
    matchType: matchType,
    organizationData: foundOrganization,
    searchResult: {
      found: true,
      searchTerm: targetClientName,
      matchedName: foundOrganization.name,
      matchType: matchType,
      organizationId: foundOrganization.id
    },
    apiEndpoints: {
      organizationDevices: `/v2/organization/${foundOrganization.id}/devices`,
      organizationInfo: `/v2/organization/${foundOrganization.id}`,
      organizationLocations: `/v2/organization/${foundOrganization.id}/locations`
    }
  }
};

// Automated Alerts - Filter & Enrich
// Filters to HaloPSA-webhook-linked conditions, joins device names, 
// builds client-friendly messages, sorts chronologically, formats dates for display

const ALLOWED_SOURCE_TYPES = [
  'CONDITION_BITLOCKER_STATUS',
  'CONDITION_WINDOWS_EVENT_LOG_TRIGGERED',
  'CONDITION_AGENT_DISK_FREE_SPACE',
];

// Maps Ninja's internal message code -> a clean, client-facing sentence
const MESSAGE_BUILDERS = {
  agent_win_cond_disk_volume_encryption_disabled: (p) =>
    `BitLocker encryption is disabled on drive ${p.drive_letter}.`,
  agent_win_cond_disk_free_le: (p) =>
    `Free disk space on drive ${p.volume} is at or below ${p.threshold}${p.unit}.`,
  agent_cond_eventlog2: (p) =>
    `A ${p.event_source} error was logged on this device (Event ID ${p.event_id}): ${p.msg}`,
};

function formatAlertDate(epochSeconds) {
  if (!epochSeconds) return 'Unknown';
  const date = new Date(epochSeconds * 1000);
  return date.toLocaleString('en-US', {
    year: 'numeric', month: 'long', day: 'numeric',
    hour: 'numeric', minute: '2-digit'
  });
}
// Build deviceId -> deviceName lookup from the devices branch
const deviceNameMap = new Map();
try {
  const deviceItems = $('Get Devices by ID1').all();
  for (const it of deviceItems) {
    const raw = it.json;
    const list = Array.isArray(raw) ? raw
      : Array.isArray(raw?.results) ? raw.results
      : Array.isArray(raw?.devices) ? raw.devices
      : [raw];
    for (const d of list) {
      if (!d) continue;
      const id = d.id ?? d.deviceId;
      const name = d.displayName ?? d.systemName ?? d.dnsName ?? d.deviceName;
      if (id !== undefined && name) deviceNameMap.set(id, name);
    }
  }
} catch (e) {
  // Get Devices by ID1 not available in this execution context
}

const incoming = $input.all();
let alerts = [];

for (const item of incoming) {
  const j = item.json;
  if (Array.isArray(j?.results)) alerts.push(...j.results);
  else if (Array.isArray(j)) alerts.push(...j);
  else if (j) alerts.push(j);
}

const filtered = alerts.filter(a => ALLOWED_SOURCE_TYPES.includes(a.sourceType));

// Enrich, keeping raw timestamp temporarily for sorting
const enriched = filtered.map(a => {
  const code = a?.data?.message?.code;
  const params = a?.data?.message?.params || {};
  const builder = MESSAGE_BUILDERS[code];

  return {
    deviceId: a.deviceId,
    deviceName: deviceNameMap.get(a.deviceId) ?? `Device ${a.deviceId}`,
    sourceType: a.sourceType,
    clientMessage: builder ? builder(params) : a.conditionName,
    _sortTime: a.createTime, // internal only, stripped before output
    dateDetected: formatAlertDate(a.createTime),
  };
});

// Sort oldest -> newest by raw timestamp
enriched.sort((x, y) => x._sortTime - y._sortTime);

// Strip internal sort field before returning to the report
return enriched.map(({ _sortTime, ...rest }) => ({ json: rest }));

// Automated Alerts - Structure by Device
// Groups the enriched alert list by device for report rendering

const items = $input.all();

const deviceMap = new Map();

for (const item of items) {
  const a = item.json;
  const key = a.deviceId;

  if (!deviceMap.has(key)) {
    deviceMap.set(key, {
      deviceId: a.deviceId,
      deviceName: a.deviceName,
      alertCount: 0,
      alerts: [],
    });
  }

  const entry = deviceMap.get(key);
  entry.alertCount += 1;
  entry.alerts.push({
    clientMessage: a.clientMessage,
    dateDetected: a.dateDetected,
  });
}

// Alphabetical by device name for predictable report ordering
const devices = Array.from(deviceMap.values())
  .sort((x, y) => x.deviceName.localeCompare(y.deviceName));

const totalActiveAlerts = devices.reduce((sum, d) => sum + d.alertCount, 0);

return [{
  json: {
    type: 'automated_alerts_summary',
    processedAt: new Date().toISOString(),
    devicesWithAlerts: devices.length,
    totalActiveAlerts,
    devices,
  }
}];

// n8n Code node — Mode: "Run Once for All Items"
// Groups patch results by deviceId, excluding REJECTED patches.

const allPatches = [];

for (const item of $input.all()) {
  const json = item.json;

  if (Array.isArray(json?.results)) {
    allPatches.push(...json.results);
  } else if (json && json.id && json.deviceId !== undefined) {
    allPatches.push(json);
  } else if (Array.isArray(json)) {
    allPatches.push(...json);
  }
}

// Filter out REJECTED patches
const pendingPatches = allPatches.filter(
  (p) => (p.status || "").toUpperCase() !== "REJECTED"
);

const byDevice = {};

for (const p of pendingPatches) {
  const key = String(p.deviceId);
  if (!byDevice[key]) {
    byDevice[key] = {
      deviceId: p.deviceId,
      patchCount: 0,
      patches: [],
      severityBreakdown: {
        IMPORTANT: 0,
        OPTIONAL: 0,
        CRITICAL: 0,
        OTHER: 0,
      },
      typeBreakdown: {},
      lastSeen: 0,
    };
  }

  const entry = byDevice[key];

  const dedupeKey = `${p.id}|${p.name}|${p.timestamp}`;
  const exists = entry.patches.some(
    (x) => `${x.id}|${x.name}|${x.timestamp}` === dedupeKey
  );
  if (exists) continue;

  const patch = {
    id: p.id,
    name: p.name,
    severity: p.severity ?? null,
    status: p.status ?? null,
    type: p.type ?? null,
    kbNumber: p.kbNumber ?? null,
    timestamp: p.timestamp ?? null,
  };
  entry.patches.push(patch);
  entry.patchCount += 1;

  const sev = (p.severity || "OTHER").toUpperCase();
  if (entry.severityBreakdown[sev] !== undefined) {
    entry.severityBreakdown[sev] += 1;
  } else {
    entry.severityBreakdown.OTHER += 1;
  }

  const t = p.type || "UNKNOWN";
  entry.typeBreakdown[t] = (entry.typeBreakdown[t] || 0) + 1;

  if (p.timestamp && p.timestamp > entry.lastSeen) {
    entry.lastSeen = p.timestamp;
  }
}

const severityRank = { CRITICAL: 0, IMPORTANT: 1, OPTIONAL: 2 };
const sortPatches = (a, b) => {
  const ra = severityRank[a.severity] ?? 9;
  const rb = severityRank[b.severity] ?? 9;
  if (ra !== rb) return ra - rb;
  return (a.name || "").localeCompare(b.name || "");
};

const output = Object.values(byDevice)
  .map((d) => {
    d.patches.sort(sortPatches);
    return d;
  })
  .sort((a, b) => a.deviceId - b.deviceId);

return output.map((d) => ({ json: d }));

// n8n Code node — Mode: "Run Once for All Items"
// Summarizes per-device patch data into deviceId + missing patch names.

const items = $input.all();

const summary = items.map((item) => {
  const d = item.json;

  return {
    json: {
      deviceId: d.deviceId,
      missingPatches: (d.patches || []).map((p) => p.name),
    },
  };
});

// Sort by deviceId ascending
summary.sort((a, b) => a.json.deviceId - b.json.deviceId);

return summary;
